<script setup lang="ts">
import { computed, reactive, ref } from "vue"; import { useRoute, useRouter } from "vue-router"; import { ElMessage } from "element-plus"; import { knowledgeApi } from "../api/knowledge"; import PdfPreview from "../components/PdfPreview.vue"; import type { KnowledgeCategory, KnowledgePreview, KnowledgeUnit, KnowledgeVersion, PermissionGrant, PermissionSet } from "../types";
const route=useRoute(); const router=useRouter(); const id=String(route.params.knowledgeId); const unit=ref<KnowledgeUnit|null>(null); const versions=ref<KnowledgeVersion[]>([]); const categories=ref<KnowledgeCategory[]>([]); const permissionSet=ref<PermissionSet|null>(null); const preview=ref<KnowledgePreview|null>(null); const previewOpen=ref(false); const editOpen=ref(false); const permissionOpen=ref(false); const deleteOpen=ref(false); const rollbackId=ref(""); const grants=ref<PermissionGrant[]>([]); const pdfBlob=ref<Blob|null>(null); const pdfOpen=ref(false); const editForm=reactive({title:"",category_id:"",tags:""});
async function load(){const [u,v,p,c]=await Promise.all([knowledgeApi.get(id),knowledgeApi.versions(id),knowledgeApi.permissions(id),knowledgeApi.categories()]);unit.value=u;versions.value=v;permissionSet.value=p;categories.value=c;Object.assign(editForm,{title:u.title,category_id:u.category_id,tags:u.tags.join(",")})}void load();
async function openPreview(versionId=""){preview.value=await knowledgeApi.preview(id,versionId);previewOpen.value=true}
async function download(versionId=""){const blob=await knowledgeApi.download(id,versionId);const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=versions.value.find(v=>v.version_id===versionId)?.filename||"knowledge-file";a.click();URL.revokeObjectURL(a.href)}
async function openPdf(version:KnowledgeVersion){pdfBlob.value=await knowledgeApi.download(id,version.version_id);pdfOpen.value=true}
async function saveEdit(){await knowledgeApi.update(id,{title:editForm.title,category_id:editForm.category_id,tags:editForm.tags.split(",").map(x=>x.trim()).filter(Boolean)});editOpen.value=false;await load()}
async function savePermissions(){await knowledgeApi.setPermissions(id,grants.value);permissionOpen.value=false;await load()}
async function rollback(){await knowledgeApi.rollback(id,rollbackId.value);ElMessage.success("回滚成功");rollbackId.value="";await load()}
async function removeKnowledge(){await knowledgeApi.remove(id);ElMessage.success("知识已删除");await router.push("/knowledge")}
const isPdf=(v:KnowledgeVersion)=>v.filename.toLowerCase().endsWith(".pdf");
</script><template><el-space direction="vertical" size="large" fill><el-card class="page-card"><template #header><div class="card-header"><span>{{unit?.title||'知识详情'}}</span><el-space><el-button @click="router.push('/knowledge')">返回</el-button><el-button @click="openPreview()">预览</el-button><el-button @click="download()">下载原文件</el-button><el-button @click="editOpen=true">编辑</el-button><el-button @click="grants=[...(permissionSet?.grants||[])];permissionOpen=true">权限配置</el-button><el-button v-if="unit?.status!=='published'" type="primary" @click="knowledgeApi.publish(id).then(load)">发布</el-button><el-button v-else @click="knowledgeApi.disable(id).then(load)">停用</el-button><el-button type="danger" @click="deleteOpen=true">删除</el-button></el-space></div></template><el-descriptions :column="2" border><el-descriptions-item label="知识 ID">{{unit?.knowledge_id}}</el-descriptions-item><el-descriptions-item label="状态">{{unit?.status}}</el-descriptions-item><el-descriptions-item label="分类">{{unit?.category_id}}</el-descriptions-item><el-descriptions-item label="当前版本">{{unit?.current_version_id}}</el-descriptions-item><el-descriptions-item label="标签" :span="2"><el-tag v-for="t in unit?.tags||[]" :key="t" class="tag-gap">{{t}}</el-tag></el-descriptions-item></el-descriptions></el-card><el-card class="page-card" header="版本历史"><el-table :data="versions"><el-table-column label="版本" width="80"><template #default="s">v{{s.row.version_no}}</template></el-table-column><el-table-column prop="filename" label="文件名"/><el-table-column prop="status" label="状态" width="120"/><el-table-column prop="created_at" label="创建时间" width="190"/><el-table-column prop="error_message" label="错误" show-overflow-tooltip/><el-table-column label="操作" width="250"><template #default="s"><el-button link @click="openPreview(s.row.version_id)">预览</el-button><el-button v-if="isPdf(s.row)" link @click="openPdf(s.row)">PDF</el-button><el-button v-if="s.row.status==='indexed' && s.row.version_id!==unit?.current_version_id" link @click="rollbackId=s.row.version_id">回滚</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="previewOpen" :title="preview?.title||'知识预览'" width="980px"><el-alert :title="'版本 v'+(preview?.version_no||'')+' · '+(preview?.chunks?.length||0)+' 个切片'" type="info" :closable="false"/><pre class="markdown-preview">{{preview?.markdown}}</pre><el-table :data="preview?.chunks||[]"><el-table-column prop="section_path" label="章节" width="220"/><el-table-column prop="content" label="内容"/></el-table></el-dialog><el-dialog v-model="pdfOpen" title="PDF 原文件预览" width="1000px"><PdfPreview :blob="pdfBlob"/></el-dialog><el-dialog v-model="editOpen" title="编辑知识"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="editForm.title"/></el-form-item><el-form-item label="分类"><el-select v-model="editForm.category_id" style="width:100%"><el-option v-for="c in categories" :key="c.category_id" :label="c.name" :value="c.category_id"/></el-select></el-form-item><el-form-item label="标签"><el-input v-model="editForm.tags"/></el-form-item></el-form><template #footer><el-button @click="editOpen=false">取消</el-button><el-button type="primary" @click="saveEdit">保存</el-button></template></el-dialog><el-dialog v-model="permissionOpen" title="四维数据权限" width="820px"><el-table :data="grants"><el-table-column label="范围" width="150"><template #default="s"><el-select v-model="s.row.scope"><el-option value="global" label="全局公开"/><el-option value="department" label="部门"/><el-option value="role" label="角色"/><el-option value="user" label="个人"/></el-select></template></el-table-column><el-table-column label="主体 ID"><template #default="s"><el-input v-model="s.row.subject_id" :disabled="s.row.scope==='global'"/></template></el-table-column><el-table-column label="含下级" width="90"><template #default="s"><el-switch v-model="s.row.include_descendants" :disabled="s.row.scope!=='department'"/></template></el-table-column><el-table-column label="操作" width="80"><template #default="s"><el-button link type="danger" @click="grants=grants.filter((_,i)=>i!==s.$index)">删除</el-button></template></el-table-column></el-table><el-button class="top-gap" @click="grants.push({scope:'department',subject_id:'',include_descendants:false})">添加规则</el-button><template #footer><el-button @click="permissionOpen=false">取消</el-button><el-button type="primary" @click="savePermissions">保存</el-button></template></el-dialog><el-dialog :model-value="Boolean(rollbackId)" title="回滚版本" @close="rollbackId=''"><p>回滚会原子切换当前检索版本。</p><template #footer><el-button @click="rollbackId=''">取消</el-button><el-button type="primary" @click="rollback">确认回滚</el-button></template></el-dialog><el-dialog v-model="deleteOpen" title="确认删除知识"><p>将物理删除版本、切片、向量和预览，操作不可恢复。</p><template #footer><el-button @click="deleteOpen=false">取消</el-button><el-button type="danger" @click="removeKnowledge">删除</el-button></template></el-dialog></el-space></template>
